    'help.start.h1': 'Bienvenido a Khayt',
    'help.start.p1': 'Khayt es un centro de gestión de producción y facturación para estudios de impresión 3D. Empieza añadiendo la información de tu negocio en Ajustes, luego añade filamento al inventario y comienza a cotizar pedidos en la Calculadora.',
    'help.start.h2': 'Conceptos clave',
    'help.start.li1': 'Los pedidos pasan por estados: Cotización → Pendiente → Imprimiendo → Posprocesado → Completado.',
    'help.start.li2': 'El tablero Kanban (pestaña Cola) muestra la producción activa de un vistazo.',
    'help.start.li3': 'Las facturas y los códigos QR se generan automáticamente a partir de los pedidos.',
    'help.calc.h1': 'Uso de la Calculadora',
    'help.calc.p1': 'Completa Pieza y material, Máquina y energía, y Mano de obra y gastos generales. Haz clic en "+ Añadir pieza al carrito" para agregar cada pieza. Establece un margen y haz clic en "Guardar cotización y enviar a la cola".',
    'help.calc.h2': 'Consejos',
    'help.calc.li1': 'Guarda configuraciones de impresora como ajustes preestablecidos para reutilizarlas rápidamente.',
