    'help.calc.li3': 'Añade una referencia de archivo/STL para registrar qué archivo se usó.',
    'help.queue.h1': 'Cola de producción',
    'help.queue.p1': 'Arrastra los pedidos (o usa los botones de estado en las tarjetas) para moverlos entre columnas. Usa las flechas arriba/abajo para reordenar los trabajos dentro de la columna Pendiente.',
    'help.invoice.h1': 'Facturas y uso compartido',
    'help.invoice.p1': 'Haz clic en "Factura" en cualquier pedido completado para ver la factura. Expórtala como PDF o compártela por WhatsApp. Los códigos QR conformes con ZATCA se añaden automáticamente cuando se activan en Ajustes.',
