    'help.start.h1': 'Bienvenue dans Khayt',
    'help.start.p1': 'Khayt est un centre de gestion de production et de facturation pour les studios d\'impression 3D. Commencez par ajouter les informations de votre entreprise dans les Paramètres, puis ajoutez du filament à l\'inventaire et commencez à établir des devis dans le Calculateur.',
    'help.start.h2': 'Concepts clés',
    'help.start.li1': 'Les commandes passent par les statuts : Devis → En attente → Impression → Post-traitement → Terminé.',
    'help.start.li2': 'Le tableau Kanban (onglet File d\'attente) affiche la production active en un coup d\'œil.',
    'help.start.li3': 'Les factures et les codes QR sont générés automatiquement à partir des commandes.',
    'help.calc.h1': 'Utiliser le Calculateur',
    'help.calc.p1': 'Renseignez Pièce et matériau, Machine et alimentation, et Main-d\'œuvre et frais généraux. Cliquez sur « + Ajouter la pièce au panier » pour ajouter chaque pièce. Définissez une marge et cliquez sur « Enregistrer le devis et envoyer à la file d\'attente ».',
    'help.calc.h2': 'Astuces',
    'help.calc.li1': 'Enregistrez les configurations d\'imprimante comme préréglages pour une réutilisation rapide.',
    'help.calc.li2': 'Attribuez un client pour appliquer automatiquement sa remise par défaut.',
    'help.calc.li3': 'Ajoutez une référence de fichier/STL pour suivre quel fichier a été utilisé.',
    'help.queue.h1': 'File d\'attente de production',
    'help.queue.p1': 'Faites glisser les commandes (ou utilisez les boutons de statut sur les cartes) pour les déplacer entre les colonnes. Utilisez les flèches haut/bas pour réorganiser les tâches dans la colonne En attente.',
    'help.invoice.h1': 'Factures et partage',
    'help.invoice.p1': 'Cliquez sur « Facture » sur n\'importe quelle commande terminée pour afficher la facture. Exportez en PDF ou partagez via WhatsApp. Les codes QR conformes à la norme ZATCA sont ajoutés automatiquement lorsqu\'ils sont activés dans les Paramètres.',
    'help.backup.h1': 'Sauvegardes',
    'help.backup.p1': 'Activez « Sauvegarde automatique une fois par jour » dans les Paramètres pour enregistrer des instantanés JSON quotidiens. Utilisez « Restaurer depuis une sauvegarde… » pour revenir à un état antérieur. Les sauvegardes peuvent également être synchronisées avec iCloud Drive sur macOS.',
